        prettyPrintVisitor.visitStatementSequenceScript(statementSequenceScript);
    }

    @Test
    public void visitVarExpr_VarExpression_PassesCorrectly() {
        VarExpr varExpr = new VarExpr("a");
        prettyPrintVisitor.visitVarExpr(varExpr);
    }

    @Test
